#!/bin/bash
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-26
# A/B: ksched_split.py --parallel against the sequential run of the same session (its analysis dir holds ksched.txt / ksched.tsv
# / ksched.release.tsv / ksched.middleware.tsv). No PG writes (--no-inst). PASS = text (minus the timing line) and all TSVs identical.
# usage: ksched_parallel_ab.sh <session_id> [analysis_dir] [out_dir]
set -u; S=${1:?session}; A=${2:-$HOME/fish_traces/analysis_$S}; O=${3:-$HOME/fish_traces/ksched_ab_$S}; mkdir -p "$O"
cd "$(dirname "$0")/../postprocess"
T0=$SECONDS
python3 ksched_split.py "$HOME/fish_traces/$S" --session-id "$S" --tsv "$O/ksched.tsv" --no-inst --parallel > "$O/ksched.txt" 2> "$O/ksched.err"; RC=$?
echo "parallel: rc=$RC in $((SECONDS - T0)) s; $(grep '^kernel:' "$O/ksched.err" | cut -c1-200)"
echo "sequential (pipeline): $(grep '^kernel:' "$A/ksched.err" | cut -c1-200)"
fail=0
for f in ksched.tsv ksched.release.tsv ksched.middleware.tsv; do
  if [ -f "$A/$f" ]; then if cmp -s "$A/$f" "$O/$f"; then echo "  $f: identical ($(wc -l < "$O/$f") lines)"; else echo "  $f: DIFFERENT"; diff "$A/$f" "$O/$f" | head -6; fail=1; fi; fi
done
if diff <(grep -v "per-instance rows" "$A/ksched.txt") <(grep -v "per-instance rows" "$O/ksched.txt") > "$O/txt.diff"; then echo "  ksched.txt: identical"; else echo "  ksched.txt: DIFFERENT ($(wc -l < "$O/txt.diff") diff lines)"; head -12 "$O/txt.diff"; fail=1; fi
[ $fail = 0 ] && echo "KSCHED PARALLEL A/B PASS" || echo "KSCHED PARALLEL A/B FAIL"
